<template><main class="gate"><section class="gate-card mc-panel"><div class="eyebrow">BLOCK CAMPUS · 阶段一</div><h1>方块校园</h1><p class="intro">从一堂课开始，<br>走进方块里的大学生活。</p><p class="muted">广东工业大学 · 广州漫游 · 摄影与收集</p>
<form v-if="!account.user" @submit.prevent="submit"><div class="row"><button type="button" class="mc-btn" @click="register=false">登录</button><button type="button" class="mc-btn" @click="register=true">注册</button></div><label>账号<input v-model="username" autocomplete="username" pattern="[a-zA-Z0-9_]{3,24}" placeholder="3–24位字母、数字或下划线" required></label><label v-if="register">手机号<input v-model="phone" autocomplete="tel" pattern="1[3-9][0-9]{9}" required></label><label>密码<input type="password" v-model="password" :autocomplete="register?'new-password':'current-password'" minlength="10" maxlength="128" required></label><button class="mc-btn primary" :disabled="busy">{{busy?'连接中…':register?'注册并进入':'登录校园'}}</button></form>
<form v-else-if="!account.identity?.verified" @submit.prevent="verify"><h2>实名占位认证</h2><p class="muted">内测自建校验，非国家实名认证接口。姓名与证件号只用于本次校验，服务端不保存原文。</p><label>姓名<input v-model="name" autocomplete="name" required></label><label>身份证号<input v-model="identity" maxlength="18" required></label><button class="mc-btn primary" :disabled="busy">校验并进入</button></form>
<div v-else><h2>{{account.user.username}}，欢迎回来</h2><p v-if="!account.identity.allowed">当前不在未成年人允许的游戏时段，或今日时长已用完。</p><button class="mc-btn primary" :disabled="!account.identity.allowed" @click="enter">进入校园</button></div>
<p role="alert" class="error">{{error}}</p><div class="row"><button class="mc-btn small" @click="guest">游客漫游</button><button v-if="account.user" class="mc-btn small" @click="logout">退出账号</button></div><p class="muted fine">游客保留旧羊城本地档，不参与账号经济及社交结算。<br>未成年人仅允许周五六日及配置节假日 20:00–21:00 游玩。</p></section><aside class="gate-art" aria-hidden="true"><div class="sun"></div><div class="building"><i v-for="n in 24" :key="n"></i><b>广东工业大学</b></div><div class="ground"></div><span>学有所成 · 行有所见</span></aside></main></template>
<script setup>
import {ref,onMounted} from 'vue'
import {account,api,logout} from '../campus/session.js'
import {store,activateAccountSave,activateGuestSave} from '../game/store.js'
const emit=defineEmits(['ready']),register=ref(false),username=ref(''),password=ref(''),phone=ref(''),name=ref(''),identity=ref(''),busy=ref(false),error=ref('')
async function run(fn){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false;password.value='';identity.value=''}}
async function state(){account.user=await api('/auth/me');account.identity=await api('/identity')}
function submit(){run(async()=>{await api(register.value?'/auth/register':'/auth/login',{username:username.value,password:password.value,...register.value?{phone:phone.value}:{}});await state()})}
function verify(){run(async()=>{account.identity=await api('/identity',{name:name.value,identity:identity.value.toUpperCase()});name.value=''})}
function enter(){run(async()=>{await activateAccountSave();emit('ready')})}
function guest(){run(async()=>{if(account.user)await api('/auth/logout',{});account.user=null;account.guest=true;activateGuestSave();emit('ready')})}
onMounted(()=>run(async()=>{try{await state()}catch(e){if(e.status!==401)throw e}}))
</script>
<style scoped>
.gate{min-height:100vh;display:grid;grid-template-columns:1fr 1fr;background:#101b21;color:#edf4db}.gate-card{align-self:center;width:min(500px,90%);margin:40px auto;padding:36px;border-color:#415951}.eyebrow{font-size:12px;letter-spacing:3px;color:#a7c7a2}h1{font-size:52px;letter-spacing:8px;margin:20px 0;color:#ffe3a1}.intro{font-size:23px;line-height:1.7}form{display:grid;gap:14px;margin:24px 0}label{display:grid;gap:7px;font-size:13px}input{padding:12px;background:#10191d;border:2px solid #54675b;color:white;width:100%}.row{display:flex;gap:12px}.fine{font-size:12px;line-height:1.7}.error{color:#ffb296;min-height:20px}.gate-art{position:relative;overflow:hidden;background:#87b5b2;min-height:100%;image-rendering:pixelated}.sun{position:absolute;width:100px;height:100px;background:#ffe5a2;top:15%;right:20%;box-shadow:20px 20px 0 #f4d98c}.building{position:absolute;left:10%;right:10%;bottom:27%;height:34%;background:#d6c6a0;border-top:24px solid #98654b;display:grid;grid-template-columns:repeat(6,1fr);gap:12px;padding:35px 20px;box-shadow:24px 24px 0 #a89d80}.building i{background:#476865;border-top:5px solid #ede2ba}.building b{position:absolute;top:3px;width:100%;text-align:center;color:#47372d;letter-spacing:8px}.ground{position:absolute;bottom:0;height:24%;width:100%;background:#74956a;border-top:30px solid #9cb481}.gate-art span{position:absolute;bottom:10%;width:100%;text-align:center;letter-spacing:6px;color:#f5efce}@media(max-width:760px){.gate{grid-template-columns:1fr}.gate-art{display:none}.gate-card{padding:24px}h1{font-size:40px}}
</style>
